    if(!this.mine)return null;
    const centre=[this.mine.x,this.mine.y,this.mine.z],stage=this.safeStagePoint();if(!stage)return this.doorCentre();
    const start=[shipX,shipY,0],protectedRadius=this.hostClearanceRadius();
