    for(let i=0;i<6&&stage&&v3len(v3sub(stage,centre))<protectedRadius+10;i++){stageDistance+=8;stage=this.stagingPoint(stageDistance)}
    this.dockStageDistance=stageDistance;stage=this.stagingPoint(stageDistance);
    if(!stage){this.dockRoute=[];this.dockRouteLeg=0;return}
    const preferred=this.doorUp;
    const planned=planLargeObjectApproach([shipX,shipY,0],centre,stage,protectedRadius,preferred);
