    this.navPulse+=dt;
    // Large destinations are persistent world objects. There is deliberately no
    // off-screen recycle/reposition rule here: flying wide leaves the SAME asteroid
    // behind the player until they turn back and reacquire it.
    const beforeQ=camPoint([this.mine.x,this.mine.y,this.mine.z]);
    // Player-relative coordinates change only because the craft physically moves.
    this.mine.x-=spaceMoveX*OPEN_SPACE_CRUISE*dt;
    this.mine.y-=spaceMoveY*OPEN_SPACE_CRUISE*dt;
    this.mine.z-=spaceMoveZ*OPEN_SPACE_CRUISE*dt;
    // Door orientation is authored into the selected asteroid-base geometry and
