    travel=0;this.outStartTravel=0;this.returnStartTravel=0;tunnelStartWorld=0;tunnelOriginX=0;
    reactorBoundaryWorld=escapeBoundaryWorld=exitDoorWorld=Infinity;
    shipX=0;shipY=-2.2;viewYaw=0;viewPitch=0;viewRoll=entryRoll;inputX=inputY=aimX=aimY=0;spaceYawVel=spacePitchVel=0;
    hazards.length=0;groundTargets.length=0;bolts.length=0;shots.length=0;playerMissiles.length=0;
    const positions=[24,48,72,88];
    const ys=[-.66,.66,-.58,.72];
    for(let i=0;i<positions.length;i++)hazards.push({type:'courierGirder',courierLocal:positions[i],z:positions[i],y:ys[i],thick:.46,clearance:.53,col:C.c,hitFx:0,dead:false,passedOut:false,passedBack:false});
