  beginDelivery(){
    if(mode==='courierDelivery')return;
    mode='courierDelivery';phase='courierTunnel';modeT=0;this.deliveryT=0;this.cargoT=0;this.cargoLanded=false;this.deliveryAnnounced=false;
    inputX=inputY=aimX=aimY=0;laserBurstRemaining=0;endLaserTrigger();
    say('AUTOPILOT · DELIVERY BAY',.8)
  }
