      // Final centring is measured in the actual camera frame, then converted back
      // to a world-space translation. This remains correct even if the doorway is
      // nowhere near canonical world +Z.
      const q=camPoint(entry);
      const lateral=Math.hypot(q[0],q[1]),align=1-Math.exp(-dt*5.8);
      if(q[2]<64)this.doorOpen=clamp(this.doorOpen+dt*.58,0,1);
      const lined=clamp(1-lateral/8,0,1),dockSpeed=lerp(8.5,18.5,lined);
